add_action( 'woocommerce_before_cart', 'perfectpixel_free_shipping_remaining_notice' );
add_action( 'woocommerce_before_checkout_form', 'perfectpixel_free_shipping_remaining_notice', 5 );

function perfectpixel_free_shipping_remaining_notice() {
	if ( ! WC()->cart || WC()->cart->is_empty() || ! WC()->cart->needs_shipping() ) {
		return;
	}
	$threshold = (float) '{{free_shipping_threshold}}';
	$remaining = $threshold - (float) WC()->cart->get_displayed_subtotal();
	if ( $threshold <= 0 || $remaining <= 0 ) {
		return;
	}
	$text = str_replace( '{amount}', wc_price( $remaining ), esc_html( '{{free_shipping_remaining_text}}' ) );
	$link = sprintf( '<a href="%s" class="button wc-forward">%s</a> ', esc_url( wc_get_page_permalink( 'shop' ) ), esc_html( '{{free_shipping_button_text}}' ) );
	wc_print_notice( $link . $text, 'notice' );
}
